namespace sv_bbc3fe44eca14248a3a53a7a3912b5c0.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the current warehouse.
/// Components subscribe to OnAlertCountChanged to react when new data arrives.
/// Scoped lifetime ensures each user circuit has independent state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _currentCount;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentCount => _currentCount;

    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query returning a random number 0–15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Start polling for the given warehouse. Multiple callers share one timer;
    /// polling stops when the last subscriber calls StopPolling.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_subscriberCount > 1) return; // already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0) return; // other subscribers still active

        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    /// <summary>
    /// Restart polling with a new warehouse (called when warehouse selection changes).
    /// </summary>
    public void RestartPolling(string warehouseId)
    {
        if (_subscriberCount == 0) return;

        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync(warehouseId);

        while (!ct.IsCancellationRequested && _timer is not null)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct))
                    break;
            }
            catch (OperationCanceledException)
            {
                break;
            }

            await FetchAndNotifyAsync(warehouseId);
        }
    }

    private async Task FetchAndNotifyAsync(string warehouseId)
    {
        var count = await GetLowStockCountAsync(warehouseId);
        _currentCount = count;
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

