@rendermode InteractiveServer
@inject WarehouseState Warehouse
@implements IDisposable
@using sv_bbc3fe44eca14248a3a53a7a3912b5c0.Services

<select class="form-select form-select-sm" value="@Warehouse.CurrentWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString() ?? "";
        var name = WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;
        Warehouse.SetWarehouse(id, name);
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        Warehouse.OnChange -= OnStateChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState Warehouse
@implements IDisposable
@using sv_bbc3fe44eca14248a3a53a7a3912b5c0.Services

<span class="badge bg-danger rounded-pill">@AlertService.CurrentCount</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertCountChanged -= _handler;
        }
    }
}

