@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState Warehouse
@implements IDisposable
@using sv_bbc3fe44eca14248a3a53a7a3912b5c0.Services

<PageTitle>Dashboard - @Warehouse.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@Warehouse.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title text-danger">Low Stock Alerts</h5>
                <p class="card-text display-4 text-danger">@AlertService.CurrentCount</p>
                <small class="text-muted">Items below minimum level</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-success">Active</span>
                    <br />
                    <small class="text-muted">Refreshing every 10 seconds</small>
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () =>
        {
            AlertService.RestartPolling(Warehouse.CurrentWarehouseId);
            InvokeAsync(StateHasChanged);
        };

        AlertService.OnAlertCountChanged += _alertHandler;
        Warehouse.OnChange += _warehouseHandler;

        // Start polling for current warehouse
        AlertService.StartPolling(Warehouse.CurrentWarehouseId);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.StopPolling();
    }
}

